import re,os
root="AlgebraicJacobian.lean"
def path(m): return m.replace('.','/')+'.lean'
seen=set()
def imports(f):
    out=[]
    try:
        for line in open(f):
            m=re.match(r'^import\s+(AlgebraicJacobian[\w.]*)',line)
            if m: out.append(m.group(1))
            elif line.strip() and not line.startswith(('import','--','/-','*','-')) and 'import' not in line:
                pass
    except FileNotFoundError: pass
    return out
stack=imports(root)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    stack+=imports(path(m))
all_mods={p[:-5].replace('/','.') for p,_,_ in [] }
mods=set()
for dirpath,_,files in os.walk("AlgebraicJacobian"):
    for fn in files:
        if fn.endswith('.lean'):
            mods.add(os.path.join(dirpath,fn)[:-5].replace('/','.'))
print("modules:",len(mods),"reachable:",len(seen & mods))
print("UNROOTED:", sorted(mods-seen))
EOF

